{
  "table": {
    "name": "account",
    "purpose": "Bank accounts (classic Czech bank dataset): one row per account, with its district, statement frequency, and creation date. Referenced by loans, cards, transactions, orders, and client dispositions."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "account_id",
      "description": "Primary key identifying the account; unique across 4500 rows and referenced by loan, disp, trans, and order tables.",
      "status": "resolved"
    },
    "col_002": {
      "role": "category",
      "name": "district_id",
      "description": "Foreign key to the district lookup table (district.col_001), indicating the geographic district where the account is held (e.g. 35 = Jablonec n. Nisou, 77 = Vsetin).",
      "status": "resolved"
    },
    "col_003": {
      "role": "category",
      "name": "statement_frequency",
      "description": "Frequency of statement issuance, in Czech: 'POPLATEK MESICNE' = monthly, 'POPLATEK TYDNE' = weekly, 'POPLATEK PO OBRATU' = after each transaction.",
      "status": "resolved"
    },
    "col_004": {
      "role": "date",
      "name": "created_date",
      "description": "Date the account was created/opened, ranging from 1993-01-01 to 1997-12-29.",
      "status": "resolved"
    }
  }
}
